Write {"file_path":"D:\code\ESI.ts\src\schemas\character.ts","content":"import { z } from 'zod';

export const CharacterInfoSchema = z.object({
  character_id: z.number(),
  name: z.string(),
  description: z.string().optional(),
  corporation_id: z.number(),
  alliance_id: z.number().optional(),
  ancestry_id: z.number().optional(),
  bloodline_id: z.number(),
  race_id: z.number(),
  gender: z.enum(['male', 'female']),
  security_status: z.number().optional(),
  title: z.string().optional(),
  birthday: z.string(),
}).passthrough();

export const CharacterPortraitSchema = z.object({
  px64x64: z.string().optional(),
  px128x128: z.string().optional(),
  px256x256: z.string().optional(),
  px512x512: z.string().optional(),
}).passthrough();

export const CharacterAttributesSchema = z.object({
  charisma: z.number(),
  intelligence: z.number(),
  memory: z.number(),
  perception: z.number(),
  willpower: z.number(),
  bonus_remaps: z.number().optional(),
  last_remap_date: z.string().optional(),
  accrued_remap_cooldown_date: z.string().optional(),
}).passthrough();

export const AgentResearchSchema = z.object({
  agent_id: z.number(),
  skill_type_id: z.number(),
  started_at: z.string(),
  points_per_day: z.number(),
  remainder_points: z.number(),
}).passthrough();

export const BlueprintSchema = z.object({
  item_id: z.number(),
  type_id: z.number(),
  location_id: z.number(),
  location_flag: z.string(),
  quantity: z.number(),
  time_efficiency: z.number(),
  material_efficiency: z.number(),
  runs: z.number(),
}).passthrough();

export const CorporationHistorySchema = z.object({
  corporation_id: z.number(),
  record_id: z.number(),
  start_date: z.string(),
  is_deleted: z.boolean().optional(),
}).passthrough();

export const JumpFatigueSchema = z.object({
  jump_fatigue_expire_date: z.string().optional(),
  last_jump_date: z.string().optional(),
  last_update_date: z.string().optional(),
}).passthrough();

export const MedalSchema = z.object({
  medal_id: z.number(),
  title: z.string(),
  description: z.string(),
  date: z.string(),
  issuer_id: z.number(),
  corporation_id: z.number(),
  reason: z.string(),
  status: z.enum(['private', 'public']),
  graphics: z.array(z.object({
    part: z.number(),
    layer: z.number(),
    graphic: z.string(),
    color: z.number().optional(),
  }).passthrough()),
}).passthrough();

export const NotificationSchema = z.object({
  notification_id: z.number(),
  type: z.string(),
  sender_id: z.number(),
  sender_type: z.enum(['character', 'corporation', 'alliance', 'faction', 'other']),
  timestamp: z.string(),
  text: z.string().optional(),
  is_read: z.boolean().optional(),
}).passthrough();

export const StandingSchema = z.object({
  from_id: z.number(),
  from_type: z.enum(['agent', 'npc_corp', 'faction']),
  standing: z.number(),
}).passthrough();

export const CharacterTitleSchema = z.object({
  title_id: z.number(),
  name: z.string(),
}).passthrough();

export const CharacterAffiliationSchema = z.object({
  character_id: z.number(),
  corporation_id: z.number(),
  alliance_id: z.number().optional(),
  faction_id: z.number().optional(),
}).passthrough();

export const CharacterRoleSchema = z.object({
  roles: z.array(z.string()).optional(),
  roles_at_hq: z.array(z.string()).optional(),
  roles_at_base: z.array(z.string()).optional(),
  roles_at_other: z.array(z.string()).optional(),
}).passthrough();
"}

